# Helpers specific to this wizard (the library above stays untouched).

# set_env_secret ENV NAME VALUE sets a GitHub Actions *environment* secret.
set_env_secret() {
  local env="$1" name="$2" value="$3"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" --env "$env" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name@$env")
      printf '  %s✓ set%s GitHub secret %s in environment %s\n' "$GREEN" "$RESET" "$name" "$env"
      return
    fi
  fi
  SKIPPED+=("GitHub environment secret $name in $env (gh secret set $name --env $env)")
  warn "skipped GitHub secret $name in $env: gh not ready or environment missing"
}

# to_clipboard copies stdin to the clipboard without echoing it.
to_clipboard() {
  if   command -v pbcopy  >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then wl-copy
  elif command -v xclip   >/dev/null 2>&1; then xclip -selection clipboard
  else return 1; fi
}

# vault_item "Vault" "Item name" reminds the human to save the clipboard in Vaultwarden.
vault_item() {
  step "In Vaultwarden, vault ${BOLD}$1${RESET}: create a Login/Secure Note named ${BOLD}$2${RESET} and paste."
  pause "Saved in Vaultwarden? Press Enter"
}

# runs N: true when stage N should run (resume with START_AT=N).
runs() { (( START_AT <= $1 )); }

run_wizard() {

TOTAL_STAGES=11
ENV_FILE=".env.setup"   # non-secret identifiers only; gitignored via .env.*
START_AT="${START_AT:-1}"
REPO=""

# Load identifiers saved by earlier runs so resumed stages and the record have them.
if [[ -f "$ENV_FILE" ]]; then set -a; # shellcheck disable=SC1090
  source "$ENV_FILE"; set +a; fi
if gh auth status >/dev/null 2>&1; then
  REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
fi

banner "nunio Phase 1: accounts, domains, and secrets"
if (( START_AT > 1 )); then
  note "Resuming at stage $START_AT; stages 1–$((START_AT - 1)) are skipped."
  _STAGE_INDEX=$((START_AT - 1))
fi

# ── 1 ─────────────────────────────────────────────────────────────────────
if runs 1; then
stage "Prerequisites"
say "Non-secret IDs are saved to $ENV_FILE (gitignored) so re-runs remember them."
say "Runtime secrets are never written to disk: you store them in Vaultwarden."
command -v openssl >/dev/null 2>&1 || { warn "openssl is required"; exit 1; }
if [[ -n "$REPO" ]]; then note "GitHub CLI logged in; repo: $REPO"
else warn "gh is not logged in (or not run from the repo root); GitHub steps will be skipped"; fi
step "Unlock Vaultwarden and create two vaults/collections: nunio-staging and nunio-prod."
pause "Vaultwarden ready? Press Enter"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if runs 2; then
stage "Domain: buy nunio.app at IONOS"
open_url "https://www.ionos.de/domains/domain-check"
step "Search for nunio.app and buy it. Do not add IONOS hosting or email packages."
note ".app domains require HTTPS everywhere (HSTS preload); Vercel handles the certificates."
note "DNS stays at IONOS for now; Phase 2 adds the app./api. records pointing to Vercel."
warn "nunio.com and nunio.de are taken. The marketing site must use a different domain (ADR-0005)."
pause "Bought nunio.app? Press Enter"
write_env DOMAIN_REGISTRAR "IONOS"
write_env PRODUCT_DOMAIN "nunio.app"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if runs 3; then
stage "GitHub: plan and deploy environments"
say "Environments and environment secrets need GitHub Pro (or Team) on a private repo."
open_url "https://github.com/settings/billing/plans"
step "Upgrade to Pro if you are on Free."
pause "On Pro or Team? Press Enter"
if [[ -n "$REPO" ]] && confirm "Create the GitHub environments 'staging' and 'production' on $REPO?"; then
  for env in staging production; do
    if gh api -X PUT "repos/$REPO/environments/$env" >/dev/null 2>&1; then
      printf '  %s✓ created%s environment %s\n' "$GREEN" "$RESET" "$env"
    else
      SKIPPED+=("GitHub environment $env (create it under repo Settings → Environments)")
      warn "couldn't create environment $env"
    fi
  done
else
  SKIPPED+=("GitHub environments staging and production")
fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if runs 4; then
stage "Vercel: Pro team and CI token"
open_url "https://vercel.com/teams/create"
step "Create (or pick) a team on the Pro plan for nunio."
step "Team Settings → General: copy the Team URL slug and the Team ID (starts team_)."
ask VERCEL_TEAM_SLUG "Team slug:"
ask VERCEL_ORG_ID "Team ID (team_…):"
write_env VERCEL_TEAM_SLUG "$VERCEL_TEAM_SLUG"
write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
set_var VERCEL_ORG_ID "$VERCEL_ORG_ID"
open_url "https://vercel.com/account/tokens"
step "Create a token named 'nunio-ci', scoped to this team, expiry 1 year (note the date)."
ask_secret VERCEL_TOKEN "Paste the token (hidden):"
set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
unset VERCEL_TOKEN
note "Projects for apps/web and apps/api are created in Phase 2, once those folders exist."
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if runs 5; then
stage "Render: Pro workspace and CI API key"
open_url "https://dashboard.render.com/"
step "Create (or pick) a workspace on the Pro plan (needed for OIDC later)."
step "Workspace Settings: copy the workspace ID (starts tea-)."
note "If the ID isn't shown there, it appears in the dashboard URL."
ask RENDER_WORKSPACE_ID "Workspace ID (tea-…):"
write_env RENDER_WORKSPACE_ID "$RENDER_WORKSPACE_ID"
step "Account Settings → API Keys: create a key named 'nunio-ci'."
ask_secret RENDER_API_KEY "Paste the API key (hidden):"
set_secret RENDER_API_KEY "$RENDER_API_KEY"
unset RENDER_API_KEY
note "The worker and parser services are created in Phase 2 (region: frankfurt)."
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if runs 6; then
stage "Neon: EU project, branches, and connection strings"
open_url "https://console.neon.tech/app/projects"
step "New project 'nunio', region AWS Europe Central 1 (Frankfurt). Postgres: latest offered."
step "Rename the default branch to 'production'; create a branch 'staging' from it."
step "Production compute: turn scale-to-zero OFF. Staging: leave it on."
step "Project settings: set the restore (point-in-time) window to 30 days or less."
warn "Confirm the region reads aws-eu-central-1 before continuing."
ask NEON_PROJECT_ID "Project ID (Settings → General):"
ask NEON_PG_VERSION "Postgres major version (e.g. 17):"
ask NEON_RESTORE_WINDOW_DAYS "Restore window in days (≤ 30):"
write_env NEON_PROJECT_ID "$NEON_PROJECT_ID"
write_env NEON_PG_VERSION "$NEON_PG_VERSION"
write_env NEON_RESTORE_WINDOW_DAYS "$NEON_RESTORE_WINDOW_DAYS"
for env in staging production; do
  step "Connect → branch '$env' → connection pooling OFF: copy the direct URL (no -pooler)."
  ask_secret NEON_URL "Paste the $env UNPOOLED URL (hidden, for CI migrations):"
  set_env_secret "$env" DATABASE_URL_UNPOOLED "$NEON_URL"
  unset NEON_URL
  step "Now toggle connection pooling ON and copy the pooled URL (-pooler host)."
  [[ "$env" == "production" ]] && vault="nunio-prod" || vault="nunio-staging"
  vault_item "$vault" "Neon DATABASE_URL (pooled, runtime)"
done
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if runs 7; then
stage "Temporal Cloud: EU namespaces and API keys"
open_url "https://cloud.temporal.io/namespaces"
step "Create namespace 'nunio-staging': cloud provider AWS, region eu-central-1 (Frankfurt),"
step "retention 7 days, authentication by API key."
step "Repeat for 'nunio-prod' with the same settings."
warn "Confirm both namespaces show aws-eu-central-1."
ask TEMPORAL_NAMESPACE_STAGING "Full staging namespace ID (nunio-staging.<account>):"
ask TEMPORAL_NAMESPACE_PROD "Full prod namespace ID (nunio-prod.<account>):"
ask TEMPORAL_ADDRESS_STAGING "Staging gRPC endpoint (…tmprl.cloud:7233):"
ask TEMPORAL_ADDRESS_PROD "Prod gRPC endpoint (…tmprl.cloud:7233):"
write_env TEMPORAL_NAMESPACE_STAGING "$TEMPORAL_NAMESPACE_STAGING"
write_env TEMPORAL_NAMESPACE_PROD "$TEMPORAL_NAMESPACE_PROD"
write_env TEMPORAL_ADDRESS_STAGING "$TEMPORAL_ADDRESS_STAGING"
write_env TEMPORAL_ADDRESS_PROD "$TEMPORAL_ADDRESS_PROD"
step "Settings → Service Accounts: create one per namespace with write access to only that"
step "namespace, then create an API key for each (note the expiry date)."
vault_item "nunio-staging" "Temporal API key (staging)"
vault_item "nunio-prod" "Temporal API key (prod)"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if runs 8; then
stage "Hetzner: Object Storage credentials (fsn1)"
open_url "https://console.hetzner.cloud/projects"
step "Create a project 'nunio'. Buckets are created in Phase 2 (compatibility spike)."
step "Security → S3 credentials: create 'nunio-staging', then 'nunio-prod'."
note "The secret key is shown only once; save each pair right away."
ask HETZNER_PROJECT "Hetzner project name:"
write_env HETZNER_PROJECT "$HETZNER_PROJECT"
write_env HETZNER_S3_ENDPOINT "https://fsn1.your-objectstorage.com"
vault_item "nunio-staging" "Hetzner S3 access + secret key (staging)"
vault_item "nunio-prod" "Hetzner S3 access + secret key (prod)"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
if runs 9; then
stage "OpenRouter: Business plan, EU routing, zero retention, API keys"
say "AI calls go through OpenRouter's EU endpoint (https://eu.openrouter.ai/api/v1)."
note "Interim choice; Bedrock (ADR-0011) remains the target. Settings UI paths may differ slightly."
open_url "https://openrouter.ai/settings"
step "Create an organization 'nunio' and upgrade it to the Business plan (needed for EU routing)."
ask OPENROUTER_ORG "Organization name or ID:"
write_env OPENROUTER_ORG "$OPENROUTER_ORG"
write_env OPENROUTER_BASE_URL "https://eu.openrouter.ai/api/v1"
step "Guardrails: restrict allowed data regions to EU, so requests not sent via eu.openrouter.ai"
step "are rejected (403). Apply it to the whole organization."
step "Privacy: enforce Zero Data Retention (ZDR) for all models, and turn OFF any"
step "'use my data for training/improvement' and input/output logging options."
warn "Do not enable Claude Fable or Mythos models (30-day retention requirement)."
pause "EU guardrail and ZDR enforced? Press Enter"
open_url "https://openrouter.ai/settings/keys"
step "Create an API key 'nunio-staging' with a monthly credit limit, then copy it."
vault_item "nunio-staging" "OpenRouter API key (staging)"
step "Create an API key 'nunio-prod' with a monthly credit limit, then copy it."
vault_item "nunio-prod" "OpenRouter API key (prod)"
note "Phase 2 verifies which Claude models and embeddings are actually served in-region."
fi

# ── 10 ────────────────────────────────────────────────────────────────────
if runs 10; then
stage "Master keys (generated locally, clipboard only)"
say "Four random 256-bit keys, version v1. Each goes straight to your clipboard;"
say "nothing is printed or written to disk."
if confirm "Generate the master keys now?"; then
  for env in staging prod; do
    for purpose in storage-wrap temporal-codec; do
      if openssl rand -base64 32 | to_clipboard; then
        say "Copied ${BOLD}${purpose}-${env}-v1${RESET} to the clipboard."
        vault_item "nunio-$env" "master key ${purpose}-${env}-v1"
      else
        warn "No clipboard tool found; run: openssl rand -base64 32 | pbcopy"
        SKIPPED+=("master key ${purpose}-${env}-v1")
      fi
    done
  done
  printf '' | to_clipboard || true
  note "Clipboard cleared."
  write_env MASTER_KEY_VERSION "v1"
else
  SKIPPED+=("master keys (re-run with START_AT=10 to generate them)")
fi
fi

# ── 11 ────────────────────────────────────────────────────────────────────
if runs 11; then
stage "Record environments (no secrets)"
mkdir -p docs/operations
cat > docs/operations/environments.md <<DOC
